let inst
function getInst() {
    if (inst) {
        return inst
    }

    const source = require('node:fs').readFileSync('./compiler.wasm')
    const typedArray = new Uint8Array(source.buffer)
    const wasmModule = new WebAssembly.Module(typedArray)

    function memchr(ptr, c, count) {
        const mem = new Uint8Array(inst.exports.memory.buffer)
        let res = 0
        for (let i = 0; i < count; i++) {
            if (mem[ptr + i] === c) return ptr + i
        }
        return res
    }

    function debug_print(ptr) {
        let i = ptr
        const mem = new Uint8Array(inst.exports.memory.buffer)
        while (i < mem.byteLength && mem[i] !== 0) i++
        const arr = mem.subarray(ptr, i)
        const result = Buffer.from(arr).toString('utf-8')
        console.log(result)
    }

    return inst = new WebAssembly.Instance(wasmModule, { env: { memchr, debug_print } })
}

function allocCString(str) {
    const b = Buffer.from(str)
    const p = inst.exports.alloc(b.byteLength + 1)
    const mem = new Uint8Array(inst.exports.memory.buffer)
    for (let i = 0; i < b.byteLength; i++) {
        mem[p + i] = b[i]
    }
    mem[p + b.byteLength] = 0
    return p
}

function readCString(p) {
    let i = p
    const mem = new Uint8Array(inst.exports.memory.buffer)
    while (i < mem.byteLength && mem[i] !== 0) i++

    const arr = mem.subarray(p, i)
    const result = Buffer.from(arr).toString('utf-8')
    inst.exports.free(p, i - p)

    return result
}

function transformSyn(source, synth) {
    const res = getInst().exports.transformSyn(allocCString(source), synth ? 1 : 0)
    const js = readCString(res)
    getInst().exports.clearArena()

    return js
}

// does not use slices
function memcpy(from, to) {
    const f = typeof from === 'number' ? new Uint8Array(inst.exports.memory.buffer, from) : new Uint8Array(from)
    const t = typeof to === 'number' ? new Uint8Array(inst.exports.memory.buffer, to) : new Uint8Array(to)
    const m = Math.min(f.byteLength, t.byteLength)
    for (let i = 0; i < m; i++) t[i] = f[i]
}

function optimizeValueGraph(b) {
    const inst = getInst()
    const p = inst.exports.alloc(b.byteLength)
    memcpy(b, p)
    const outLenPtr = inst.exports.alloc(4) // u32
    const res = inst.exports.optimizeValueGraph(p, b.byteLength, outLenPtr)
    const outLen = new DataView(inst.exports.memory.buffer).getUint32(outLenPtr, true)
    const txt = new TextDecoder().decode(new Uint8Array(inst.exports.memory.buffer, res, outLen))
    inst.exports.clearArena()
    return txt
}

